25	// Chart 返回患者的完整档案，包含所有草稿、全部版本（含旧内容、版本关系
26	// 与更正原因）以及审计事件。仅供内部使用者；患者停用后仍可查看。
27	func (s *Store) Chart(actor Actor, patientID ID) (PatientChart, error) {
28		if !actor.valid() || !actor.IsInternal() {
29			return PatientChart{}, ErrAccessDenied
30		}
31		var chart PatientChart
32		err := s.view(func(snap *snapshot) error {
33			p, err := requirePatient(snap, patientID)
34			if err != nil {
35				return err
36			}
37			chart.Patient = *p
38	
39			for _, e := range snap.Encounters {
40				if e.PatientID == patientID {
41					chart.Encounters = append(chart.Encounters, *e)
42				}
43			}
44			sortEncounters(chart.Encounters)
45	
46			var recs []*Record
47			for _, r := range snap.Records {
48				if r.PatientID == patientID {
49					recs = append(recs, r)
50				}
51			}
52			sort.Slice(recs, func(i, j int) bool { return recs[i].ID < recs[j].ID })
53	
54			for _, r := range recs {
55				chart.Records = append(chart.Records, buildHistory(snap, r))
56			}
57	
58			chart.AuditEvents = auditEventsFor(snap, patientID)
59			return nil
60		})
61		return chart, err
62	}
63	
64	// AuditEvents 仅供内部使用者按患者查看审计事件，按发生时间旧到新。
65	// 独立查询：只整理审计历史，不连带就诊、草稿与版本历史；患者停用后仍可查看。
66	func (s *Store) AuditEvents(actor Actor, patientID ID) ([]AuditEvent, error) {
67		if !actor.valid() || !actor.IsInternal() {
68			return nil, ErrAccessDenied
69		}
70		var events []AuditEvent
71		err := s.view(func(snap *snapshot) error {
72			if _, err := requirePatient(snap, patientID); err != nil {
73				return err
74			}
75			events = auditEventsFor(snap, patientID)
76			return nil
77		})
78		if err != nil {
79			return nil, err
80		}
81		return events, nil
82	}
83	
84	// auditEventsFor 收集指定患者的全部审计事件，是 AuditEvents 与 Chart 共用的
85	// 规则：按追加顺序（即真实发生顺序；时间戳相同时也保持操作先后）逐条拷贝，
86	// 返回的列表与存储侧完全脱离，调用方的本地整理不会写回正式历史。
87	func auditEventsFor(snap *snapshot, patientID ID) []AuditEvent {
88		var events []AuditEvent
89		for _, ev := range snap.AuditEvents {
90			if ev.PatientID == patientID {
91				events = append(events, *ev)
92			}
93		}
94		return events
95	}
96	
97	// EncounterRecords 仅供内部使用者查看某次就诊下的记录及完整历史。
98	func (s *Store) EncounterRecords(actor Actor, patientID, encounterID ID) ([]RecordHistory, error) {
99		if !actor.valid() || !actor.IsInternal() {
100			return nil, ErrAccessDenied
101		}
102		var out []RecordHistory
103		err := s.view(func(snap *snapshot) error {
104			if _, err := requirePatient(snap, patientID); err != nil {
105				return err
106			}
107			if _, err := requireEncounter(snap, patientID, encounterID); err != nil {
108				return err
109			}
110			var recs []*Record
111			for _, r := range snap.Records {
112				if r.EncounterID == encounterID {
113					recs = append(recs, r)
114				}
115			}
116			sort.Slice(recs, func(i, j int) bool { return recs[i].ID < recs[j].ID })
117			for _, r := range recs {
118				out = append(out, buildHistory(snap, r))
119			}
120			return nil
121		})
122		return out, err
123	}
124	
125	func buildHistory(snap *snapshot, r *Record) RecordHistory {
126		// 返回的记录必须是独立副本：Versions 切片与存储中的记录共享底层数组时，
127		// 调用方改动查询结果会写回正式历史。这里深拷贝，保证修改手中的结果
128		// 只影响该结果本身。
129		rec := *r
130		rec.Versions = append([]ID(nil), r.Versions...)
131		rh := RecordHistory{
132			Record:       rec,
133			DraftContent: r.DraftContent,
134			HasDraft:     r.HasDraft,
135		}
136		for _, vid := range r.Versions {
137			if v := snap.Versions[vid]; v != nil {
138				rh.Versions = append(rh.Versions, *v)
139			}
140		}
141		sort.Slice(rh.Versions, func(i, j int) bool { return rh.Versions[i].Number < rh.Versions[j].Number })
142		if r.CurrentVersionID != "" {
143			if v := snap.Versions[r.CurrentVersionID]; v != nil {
144				cv := *v
145				rh.CurrentVersion = &cv
146			}
147		}
148		return rh
149	}
150	
151	// currentEffective 取出记录当前生效版本的对外内容；无生效版本时第二返回值为 false。
152	func currentEffective(snap *snapshot, r *Record) (EffectiveRecord, bool) {
153		if r.CurrentVersionID == "" {
154			return EffectiveRecord{}, false
155		}
156		v := snap.Versions[r.CurrentVersionID]
157		if v == nil {
158			return EffectiveRecord{}, false
159		}
160		return EffectiveRecord{
161			RecordID:    r.ID,
162			VersionID:   v.ID,
163			Version:     v.Number,
164			Content:     v.Content,
165			EffectiveAt: v.CreatedAt,
166		}, true
167	}
168	
169	func sortEncounters(es []Encounter) {
170		sort.Slice(es, func(i, j int) bool {
171			if !es[i].OccurredAt.Equal(es[j].OccurredAt) {
172				return es[i].OccurredAt.Before(es[j].OccurredAt)
173			}
174			return es[i].ID < es[j].ID
175		})
176	}
