1	package clinical
2	
3	import (
4		"errors"
5		"reflect"
6		"testing"
7		"time"
8	)
9	
10	// 本文件覆盖诊断/医嘱正文的保存一致性：正文夹带任何无效 UTF-8 字节时，
11	// 新建草稿、修改草稿与更正生效记录都必须整体返回 ErrInvalidArgument，
12	// 不能靠静默替换（U+FFFD）、截断或跳过坏字节继续保存；合法 UTF-8 正文
13	// （含中文、表情、组合字符、换行、引号、反斜杠、首尾空白与用户明确输入
14	// 的合法 U+FFFD）必须原样保存，当次查询与关闭后从同一位置重新打开看到
15	// 的正文逐字相同。
16	
17	// invalidContents 是各类无效 UTF-8 正文：坏序列出现在开头、结尾、中间，
18	// 夹在合法中文之间，孤立续字节，不完整多字节字符，单个非法字节，
19	// overlong 编码与 UTF-16 代理项编码；另有一例在合法 U+FFFD 之后紧跟
20	// 非法字节——必须因那个坏字节被拒绝，而不是把整串当成合法替换字符。
21	var invalidContents = []struct {
22		label   string
23		content string
24	}{
25		{"开头非法字节", "\xff诊断：高血压 I10"},
26		{"结尾非法字节", "诊断：高血压 I10\xff"},
27		{"中间非法字节夹在中文之间", "诊\xff断：高血压"},
28		{"合法中文之间夹坏字节", "高血压 I10（复\xfe核确认）"},
29		{"孤立续字节", "血压 120/80\x80 mmHg"},
30		{"结尾不完整多字节字符", "诊断：高血压 I10\xe6"},
31		{"中间不完整多字节序列", "abc\xe6\x9ddef"},
32		{"中文之后截断三字节序列", "高血压 I10（复核\xe7\xa1"},
33		{"单个非法字节", "\x80"},
34		{"overlong 编码", "\xc0\x80"},
35		{"UTF-16 代理项编码", "第一行\n\xed\xa0\x80\n第二行"},
36		{"合法替换字符后紧跟非法字节", "补充\ufffd\xff"},
37	}
38	
39	// validContents 是必须逐字原样保存的合法 UTF-8 正文。
40	var validContents = []struct {
41		label   string
42		content string
43	}{
44		{"中文与全角标点", "诊断：高血压 I10（复核确认）"},
45		{"表情字符", "血糖偏高 🩸，建议复诊 😷"},
46		{"组合字符", "e\u0301leve\u0301 与组合字符测试"},
47		{"多码位表情", "值班：👩🏽‍⚕️ 随访 👨‍👩‍👧"},
48		{"换行引号反斜杠", "  第一行\n第二行\t\"引号\" 与 C:\\路径  "},
49		{"首尾空白", "\t\n  正文内容保持原样  \r\n "},
50		{"用户明确输入的合法替换字符", "补充说明\ufffd（用户明确输入的 U+FFFD）"},
51	}
52	
53	// TestCreateDraftRejectsInvalidUTF8 覆盖新建草稿：任何夹带无效 UTF-8 的正文
54	// 都返回 ErrInvalidArgument，不留下新记录、不产生任何状态变化（关闭重开
55	// 后同样不存在）。诊断与医嘱两个类别都适用。空白正文继续按既有规则拒绝。
56	func TestCreateDraftRejectsInvalidUTF8(t *testing.T) {
57		for _, category := range []string{Diagnosis, Order} {
58			for _, tc := range invalidContents {
59				t.Run(category+"/"+tc.label, func(t *testing.T) {
60					dir := t.TempDir()
61					clk := &fakeClock{t: time.Date(2026, 5, 1, 9, 0, 0, 0, time.UTC)}
62					open := func() *Store {
63						s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
64						if err != nil {
65							t.Fatalf("open: %v", err)
66						}
67						return s
68					}
69	
70					s := open()
71					p, err := s.RegisterPatient(doc, "无效UTF8新建草稿患者")
72					if err != nil {
73						t.Fatal(err)
74					}
75					e, err := s.AddEncounter(doc, p.ID, time.Time{})
76					if err != nil {
77						t.Fatal(err)
78					}
79	
80					before := countRecords(s)
81					if _, err := s.CreateDraft(doc, p.ID, e.ID, category, tc.content); !errors.Is(err, ErrInvalidArgument) {
82						t.Fatalf("CreateDraft(%q) err = %v, want ErrInvalidArgument", tc.content, err)
83					}
84					// 拒绝新建不能留下新记录：档案与记录数都与提交前一致。
85					if got := countRecords(s); got != before {
86						t.Fatalf("rejected create left records: count before=%d after=%d", before, got)
87					}
88					chart, err := s.Chart(doc, p.ID)
89					if err != nil {
90						t.Fatal(err)
91					}
92					if len(chart.Records) != 0 {
93						t.Fatalf("rejected create left a record: %+v", chart.Records)
94					}
95					// 坏字节没有被落盘：关闭重开后仍无记录。
96					s = reopenStore(t, s, dir, clk)
97					if got := countRecords(s); got != before {
98						t.Fatalf("rejected create persisted after reopen: count=%d", got)
99					}
100					chart, err = s.Chart(doc, p.ID)
101					if err != nil {
102						t.Fatal(err)
103					}
104					if len(chart.Records) != 0 {
105						t.Fatalf("rejected create left a record after reopen: %+v", chart.Records)
106					}
107					_ = s.Close()
108				})
109			}
110		}
111	
112		// 空串与全空白正文继续按既有规则拒绝。
113		s, _ := newTestStore(t)
114		pid, eid := setupPatientEncounter(t, s)
115		for _, blank := range []string{"", " ", "\n\t\r ", "　"} {
116			if _, err := s.CreateDraft(doc, pid, eid, Diagnosis, blank); !errors.Is(err, ErrInvalidArgument) {
117				t.Fatalf("CreateDraft blank content %q err = %v, want ErrInvalidArgument", blank, err)
118			}
119		}
120		if got := countRecords(s); got != 0 {
121			t.Fatalf("blank creates left records: %d", got)
122		}
123	
124		// 接收方身份不能新建草稿：既有身份权限保持不变。
125		if _, err := s.CreateDraft(rcv, pid, eid, Diagnosis, "接收方试图建草稿"); !errors.Is(err, ErrAccessDenied) {
126			t.Fatalf("receiver CreateDraft err = %v, want ErrAccessDenied", err)
127		}
128	}
129	
130	// TestCreateDraftValidUTF8PreservedRoundTrip 覆盖合法正文的新建草稿：
131	// 当次查询与关闭后重新打开看到相同原文，不做任何字符形态统一或排版整理。
132	func TestCreateDraftValidUTF8PreservedRoundTrip(t *testing.T) {
133		for _, tc := range validContents {
134			t.Run(tc.label, func(t *testing.T) {
135				dir := t.TempDir()
136				clk := &fakeClock{t: time.Date(2026, 5, 2, 9, 0, 0, 0, time.UTC)}
137				open := func() *Store {
138					s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
139					if err != nil {
140						t.Fatalf("open: %v", err)
141					}
142					return s
143				}
144	
145				s := open()
146				p, err := s.RegisterPatient(doc, "合法UTF8新建草稿患者")
147				if err != nil {
148					t.Fatal(err)
149				}
150				e, err := s.AddEncounter(doc, p.ID, time.Time{})
151				if err != nil {
152					t.Fatal(err)
153				}
154				r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, tc.content)
155				if err != nil {
156					t.Fatalf("CreateDraft: %v", err)
157				}
158				if r.DraftContent != tc.content {
159					t.Fatalf("returned draft content = %q, want %q", r.DraftContent, tc.content)
160				}
161				chart, err := s.Chart(doc, p.ID)
162				if err != nil {
163					t.Fatal(err)
164				}
165				hist := findHistory(chart, r.ID)
166				if hist == nil || hist.DraftContent != tc.content {
167					t.Fatalf("chart content = %+v, want %q", hist, tc.content)
168				}
169	
170				// 关闭后从同一位置重新打开：正文逐字保持。
171				s = reopenStore(t, s, dir, clk)
172				t.Cleanup(func() { _ = s.Close() })
173				chart, err = s.Chart(doc, p.ID)
174				if err != nil {
175					t.Fatal(err)
176				}
177				hist = findHistory(chart, r.ID)
178				if hist == nil || !hist.HasDraft || hist.DraftContent != tc.content {
179					t.Fatalf("draft content after reopen = %+v, want %q", hist, tc.content)
180				}
181	
182				// 生效后第 1 版固化同一份原文，重开后仍一致。
183				v1, err := s.ActivateRecord(doc, r.ID)
184				if err != nil {
185					t.Fatal(err)
186				}
187				if v1.Content != tc.content {
188					t.Fatalf("activated content = %q, want %q", v1.Content, tc.content)
189				}
190				s = reopenStore(t, s, dir, clk)
191				t.Cleanup(func() { _ = s.Close() })
192				chart, err = s.Chart(doc, p.ID)
193				if err != nil {
194					t.Fatal(err)
195				}
196				hist = findHistory(chart, r.ID)
197				if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.Content != tc.content {
198					t.Fatalf("active content after reopen = %+v, want %q", hist, tc.content)
199				}
200			})
201		}
202	}
203	
204	// TestUpdateDraftRejectsInvalidUTF8 覆盖修改草稿：坏字节正文返回
205	// ErrInvalidArgument，原草稿的正文与状态保持不变（无版本、无审计变化），
206	// 重开后亦然；拒绝后仍可用合法正文成功修改，原文逐字保留。
207	func TestUpdateDraftRejectsInvalidUTF8(t *testing.T) {
208		dir := t.TempDir()
209		clk := &fakeClock{t: time.Date(2026, 5, 3, 9, 0, 0, 0, time.UTC)}
210		open := func() *Store {
211			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
212			if err != nil {
213				t.Fatalf("open: %v", err)
214			}
215			return s
216		}
217	
218		s := open()
219		p, err := s.RegisterPatient(doc, "无效UTF8改草稿患者")
220		if err != nil {
221			t.Fatal(err)
222		}
223		e, err := s.AddEncounter(doc, p.ID, time.Time{})
224		if err != nil {
225			t.Fatal(err)
226		}
227		original := "原草稿：血压 120/80\n待补充 "
228		target, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, original)
229		if err != nil {
230			t.Fatal(err)
231		}
232		auditBefore, err := s.AuditEvents(doc, p.ID)
233		if err != nil {
234			t.Fatal(err)
235		}
236	
237		// 各类坏序列一律拒绝；个别字节不合法也不能保留其余合法部分。
238		for _, tc := range invalidContents {
239			if _, err := s.UpdateDraft(doc, target.ID, tc.content); !errors.Is(err, ErrInvalidArgument) {
240				t.Fatalf("%s: UpdateDraft err = %v, want ErrInvalidArgument", tc.label, err)
241			}
242			chart, err := s.Chart(doc, p.ID)
243			if err != nil {
244				t.Fatal(err)
245			}
246			hist := findHistory(chart, target.ID)
247			if hist == nil || !hist.HasDraft || hist.DraftContent != original ||
248				hist.CurrentVersion != nil || len(hist.Versions) != 0 {
249				t.Fatalf("%s: rejected update changed the draft: %+v", tc.label, hist)
250			}
251			audit, err := s.AuditEvents(doc, p.ID)
252			if err != nil {
253				t.Fatal(err)
254			}
255			if !reflect.DeepEqual(audit, auditBefore) {
256				t.Fatalf("%s: audit changed after rejected update", tc.label)
257			}
258		}
259	
260		// 拒绝后重开：原草稿正文与状态仍在，坏字节从未落盘。
261		s = reopenStore(t, s, dir, clk)
262		chart, err := s.Chart(doc, p.ID)
263		if err != nil {
264			t.Fatal(err)
265		}
266		hist := findHistory(chart, target.ID)
267		if hist == nil || !hist.HasDraft || hist.DraftContent != original {
268			t.Fatalf("draft changed after rejected updates + reopen: %+v", hist)
269		}
270	
271		// 空白正文继续被拒绝，原草稿保留。
272		if _, err := s.UpdateDraft(doc, target.ID, "  \n\t "); !errors.Is(err, ErrInvalidArgument) {
273			t.Fatalf("blank update err = %v, want ErrInvalidArgument", err)
274		}
275		chart, err = s.Chart(doc, p.ID)
276		if err != nil {
277			t.Fatal(err)
278		}
279		if hist = findHistory(chart, target.ID); hist == nil || hist.DraftContent != original {
280			t.Fatalf("rejected blank update changed the draft: %+v", hist)
281		}
282	
283		// 失败后可以提交一份合法正文（含表情、组合字符、换行引号反斜杠、
284		// 首尾空白与合法 U+FFFD），当次与重开后逐字一致。
285		valid := "\t 新正文 🩸 e\u0301\n\"引号\" C:\\路径 \ufffd  "
286		updated, err := s.UpdateDraft(doc, target.ID, valid)
287		if err != nil {
288			t.Fatalf("valid update after rejections: %v", err)
289		}
290		if updated.DraftContent != valid {
291			t.Fatalf("updated draft content = %q, want %q", updated.DraftContent, valid)
292		}
293		s = reopenStore(t, s, dir, clk)
294		t.Cleanup(func() { _ = s.Close() })
295		chart, err = s.Chart(doc, p.ID)
296		if err != nil {
297			t.Fatal(err)
298		}
299		hist = findHistory(chart, target.ID)
300		if hist == nil || !hist.HasDraft || hist.DraftContent != valid {
301			t.Fatalf("valid content after reopen = %+v, want %q", hist, valid)
302		}
303	
304		// 生效固化最后一次成功保存的合法正文，而不是任何被拒绝的内容。
305		v1, err := s.ActivateRecord(doc, target.ID)
306		if err != nil {
307			t.Fatal(err)
308		}
309		if v1.Content != valid {
310			t.Fatalf("v1 content = %q, want %q", v1.Content, valid)
311		}
312		// 已生效记录不能再走草稿路径：既有规则保持不变。
313		if _, err := s.UpdateDraft(doc, target.ID, "生效后试图覆盖"); !errors.Is(err, ErrActive) {
314			t.Fatalf("update active record err = %v, want ErrActive", err)
315		}
316	}
317	
318	// TestCorrectRecordRejectsInvalidUTF8 覆盖更正生效记录：坏字节正文返回
319	// ErrInvalidArgument，当前版本、旧版本内容、版本关系（PrevID）与原因
320	// 全部保持，不生成新版本、不新增更正审计，接收方读取不变；拒绝后仍可用
321	// 此前的当前版本号提交合法正文完成一次真正的更正。
322	func TestCorrectRecordRejectsInvalidUTF8(t *testing.T) {
323		dir := t.TempDir()
324		clk := &fakeClock{t: time.Date(2026, 5, 4, 9, 0, 0, 0, time.UTC)}
325		open := func() *Store {
326			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
327			if err != nil {
328				t.Fatalf("open: %v", err)
329			}
330			return s
331		}
332	
333		s := open()
334		p, err := s.RegisterPatient(doc, "无效UTF8更正患者")
335		if err != nil {
336			t.Fatal(err)
337		}
338		e, err := s.AddEncounter(doc, p.ID, time.Time{})
339		if err != nil {
340			t.Fatal(err)
341		}
342		r, err := s.CreateDraft(doc, p.ID, e.ID, Diagnosis, "初诊：高血压 I10")
343		if err != nil {
344			t.Fatal(err)
345		}
346		v1, err := s.ActivateRecord(doc, r.ID)
347		if err != nil {
348			t.Fatal(err)
349		}
350		clk.t = clk.t.Add(time.Hour)
351		v2, err := s.CorrectRecord(doc, r.ID, 1, "复诊：高血压 I10（控制稳定）", "复核更新")
352		if err != nil {
353			t.Fatal(err)
354		}
355		if _, err := s.Grant(doc, p.ID, rcv.ID,
356			[]Scope{{EncounterID: e.ID, Category: Diagnosis}},
357			clk.t.Add(-time.Hour), clk.t.Add(48*time.Hour)); err != nil {
358			t.Fatal(err)
359		}
360	
361		chartBefore, err := s.Chart(doc, p.ID)
362		if err != nil {
363			t.Fatal(err)
364		}
365		histBefore := findHistory(chartBefore, r.ID)
366		auditBefore, err := s.AuditEvents(doc, p.ID)
367		if err != nil {
368			t.Fatal(err)
369		}
370		readBefore, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
371		if err != nil {
372			t.Fatal(err)
373		}
374	
375		// 所有坏序列（出现在开头/中间/结尾、夹在中文之间、单个坏字节等）
376		// 都用当前版本号 2 提交：一律 ErrInvalidArgument，历史与审计原样。
377		for _, tc := range invalidContents {
378			if _, err := s.CorrectRecord(doc, r.ID, 2, tc.content, "更正原因合法"); !errors.Is(err, ErrInvalidArgument) {
379				t.Fatalf("%s: CorrectRecord err = %v, want ErrInvalidArgument", tc.label, err)
380			}
381			chart, err := s.Chart(doc, p.ID)
382			if err != nil {
383				t.Fatal(err)
384			}
385			hist := findHistory(chart, r.ID)
386			if hist == nil || hist.CurrentVersion == nil {
387				t.Fatalf("%s: history missing", tc.label)
388			}
389			cur := hist.CurrentVersion
390			if cur.ID != v2.ID || cur.Number != 2 || cur.Content != v2.Content ||
391				cur.PrevID != v1.ID || cur.Reason != v2.Reason {
392				t.Fatalf("%s: current version changed: %+v", tc.label, cur)
393			}
394			if hist.Record.CurrentVersionID != v2.ID || len(hist.Versions) != 2 ||
395				!reflect.DeepEqual(hist.Record.Versions, []ID{v1.ID, v2.ID}) ||
396				!reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
397				t.Fatalf("%s: version history changed: %+v", tc.label, hist)
398			}
399			audit, err := s.AuditEvents(doc, p.ID)
400			if err != nil {
401				t.Fatal(err)
402			}
403			if !reflect.DeepEqual(audit, auditBefore) {
404				t.Fatalf("%s: correction audit added on rejected correction", tc.label)
405			}
406			res, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
407			if err != nil {
408				t.Fatal(err)
409			}
410			if !reflect.DeepEqual(res, readBefore) {
411				t.Fatalf("%s: receiver read changed:\nbefore: %+v\nafter:  %+v", tc.label, readBefore, res)
412			}
413		}
414	
415		// 拒绝后重开：当前版本、旧版本与版本关系仍是原来的结果。
416		s = reopenStore(t, s, dir, clk)
417		if got := findHistory(mustChart(t, s, p.ID), r.ID); !reflect.DeepEqual(got, histBefore) {
418			t.Fatalf("history changed after rejected corrections + reopen:\nbefore: %+v\nafter:  %+v", histBefore, got)
419		}
420	
421		// 空串与全空白正文继续按既有规则拒绝，历史不变。
422		for _, blank := range []string{"", "  \n\t ", "　"} {
423			if _, err := s.CorrectRecord(doc, r.ID, 2, blank, "原因"); !errors.Is(err, ErrInvalidArgument) {
424				t.Fatalf("blank correction %q err = %v, want ErrInvalidArgument", blank, err)
425			}
426		}
427		if got := findHistory(mustChart(t, s, p.ID), r.ID); !reflect.DeepEqual(got, histBefore) {
428			t.Fatalf("blank correction changed history: %+v", got)
429		}
430	
431		// 失败的更正没有推进版本号：仍用此前的当前版本号 2 提交合法正文，
432		// 成功生成紧接 v2 的第 3 版，只新增这一次真正完成的更正审计。
433		clk.t = clk.t.Add(time.Hour)
434		valid := "三次复诊：血压 118/76 🩸，e\u0301 组合\n\"引号\" C:\\路径 \ufffd 随访  "
435		v3, err := s.CorrectRecord(doc, r.ID, 2, valid, "坏字节拒绝后的合法更正")
436		if err != nil {
437			t.Fatalf("valid correction after rejections: %v", err)
438		}
439		if v3.Number != 3 || v3.PrevID != v2.ID || v3.Content != valid ||
440			v3.Reason != "坏字节拒绝后的合法更正" || !v3.CreatedAt.Equal(clk.t) {
441			t.Fatalf("unexpected v3: %+v", v3)
442		}
443	
444		chart, err := s.Chart(doc, p.ID)
445		if err != nil {
446			t.Fatal(err)
447		}
448		hist := findHistory(chart, r.ID)
449		if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v3.ID ||
450			len(hist.Versions) != 3 ||
451			!reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) ||
452			!reflect.DeepEqual(hist.Versions[2], v3) {
453			t.Fatalf("history after valid correction: %+v", hist)
454		}
455		audit, err := s.AuditEvents(doc, p.ID)
456		if err != nil {
457			t.Fatal(err)
458		}
459		if len(audit) != len(auditBefore)+1 || !reflect.DeepEqual(audit[:len(auditBefore)], auditBefore) {
460			t.Fatalf("audit after valid correction:\nbefore: %+v\nafter:  %+v", auditBefore, audit)
461		}
462		last := audit[len(audit)-1]
463		if last.Action != ActionCorrected || last.ObjectID != r.ID || last.ActorID != doc.ID {
464			t.Fatalf("unexpected new audit event: %+v", last)
465		}
466	
467		// 合法正文的既有版本号校验继续成立：过期版本号返回 ErrConflict，
468		// 状态与审计不变。
469		if _, err := s.CorrectRecord(doc, r.ID, 2, "用过期版本号更正", "过期"); !errors.Is(err, ErrConflict) {
470			t.Fatalf("stale version correction err = %v, want ErrConflict", err)
471		}
472		chart, err = s.Chart(doc, p.ID)
473		if err != nil {
474			t.Fatal(err)
475		}
476		if hist = findHistory(chart, r.ID); hist.CurrentVersion.ID != v3.ID || len(hist.Versions) != 3 {
477			t.Fatalf("rejected stale correction changed history: %+v", hist)
478		}
479		audit2, err := s.AuditEvents(doc, p.ID)
480		if err != nil {
481			t.Fatal(err)
482		}
483		if !reflect.DeepEqual(audit2, audit) {
484			t.Fatal("rejected stale correction added an audit event")
485		}
486	
487		// 接收方读到新的当前版本，合法正文逐字一致。
488		res, err := s.Read(rcv, p.ID, e.ID, Diagnosis)
489		if err != nil {
490			t.Fatal(err)
491		}
492		if len(res.Records) != 1 || res.Records[0].VersionID != v3.ID ||
493			res.Records[0].Version != 3 || res.Records[0].Content != valid {
494			t.Fatalf("receiver read after valid correction: %+v", res.Records)
495		}
496	
497		// 关闭后从同一位置重新打开：三个版本（含各自原文、PrevID 与原因）
498		// 与审计完整保持，当前版本仍是逐字原文的第 3 版。
499		s = reopenStore(t, s, dir, clk)
500		t.Cleanup(func() { _ = s.Close() })
501		chart, err = s.Chart(doc, p.ID)
502		if err != nil {
503			t.Fatal(err)
504		}
505		hist = findHistory(chart, r.ID)
506		if hist == nil || len(hist.Versions) != 3 {
507			t.Fatalf("history after reopen: %+v", hist)
508		}
509		if !reflect.DeepEqual(hist.Versions[0], v1) || !reflect.DeepEqual(hist.Versions[1], v2) {
510			t.Fatalf("older versions changed after reopen: %+v", hist.Versions)
511		}
512		if got := hist.Versions[2]; got.Content != valid || got.PrevID != v2.ID ||
513			got.Reason != "坏字节拒绝后的合法更正" {
514			t.Fatalf("v3 after reopen mismatch: %+v", got)
515		}
516		audit3, err := s.AuditEvents(doc, p.ID)
517		if err != nil {
518			t.Fatal(err)
519		}
520		if !reflect.DeepEqual(audit3, audit) {
521			t.Fatal("audit events changed after reopen")
522		}
523	}
524	
525	// TestInvalidUTF8RejectedWhenPatientDeactivated 保证 UTF-8 校验先行：
526	// 患者停用后夹带坏字节的写操作仍返回 ErrInvalidArgument（而非以停用错误
527	// 落盘或静默保存），且状态不变。
528	func TestInvalidUTF8RejectedWhenPatientDeactivated(t *testing.T) {
529		s, clk := newTestStore(t)
530		pid, eid := setupPatientEncounter(t, s)
531		r, err := s.CreateDraft(doc, pid, eid, Order, "医嘱草稿原文")
532		if err != nil {
533			t.Fatal(err)
534		}
535		v1, err := s.ActivateRecord(doc, r.ID)
536		if err != nil {
537			t.Fatal(err)
538		}
539		clk.t = clk.t.Add(time.Hour)
540		if err := s.DeactivatePatient(doc, pid); err != nil {
541			t.Fatal(err)
542		}
543	
544		if _, err := s.CreateDraft(doc, pid, eid, Order, "停用后\xff坏草稿"); !errors.Is(err, ErrInvalidArgument) {
545			t.Fatalf("deactivated create with bad utf8 err = %v, want ErrInvalidArgument", err)
546		}
547		if _, err := s.UpdateDraft(doc, r.ID, "停用后\xff坏草稿"); !errors.Is(err, ErrInvalidArgument) {
548			t.Fatalf("update active record with bad utf8 err = %v, want ErrInvalidArgument", err)
549		}
550		if _, err := s.CorrectRecord(doc, r.ID, 1, "停用后\xff坏更正", "原因"); !errors.Is(err, ErrInvalidArgument) {
551			t.Fatalf("deactivated correct with bad utf8 err = %v, want ErrInvalidArgument", err)
552		}
553		chart, err := s.Chart(doc, pid)
554		if err != nil {
555			t.Fatal(err)
556		}
557		hist := findHistory(chart, r.ID)
558		if hist == nil || hist.CurrentVersion == nil || hist.CurrentVersion.ID != v1.ID ||
559			len(hist.Versions) != 1 {
560			t.Fatalf("bad-utf8 writes after deactivation changed history: %+v", hist)
561		}
562	}
563	
564	// reopenStore 关闭现有句柄并从同一目录重新打开（沿用注入时钟）。
565	func reopenStore(t *testing.T, s *Store, dir string, clk *fakeClock) *Store {
566		t.Helper()
567		if err := s.Close(); err != nil {
568			t.Fatalf("close: %v", err)
569		}
570		s2, err := Open(dir, WithClock(func() time.Time { return clk.t }))
571		if err != nil {
572			t.Fatalf("reopen: %v", err)
573		}
574		return s2
575	}
576	
577	func mustChart(t *testing.T, s *Store, patientID ID) PatientChart {
578		t.Helper()
579		chart, err := s.Chart(doc, patientID)
580		if err != nil {
581			t.Fatalf("chart: %v", err)
582		}
583		return chart
584	}
