6		"testing"
7		"time"
8	)
9	
10	// 本文件覆盖拒绝回执原因的 UTF-8 校验与保存一致性：拒绝原因夹带任何无效
11	// UTF-8 字节（含不完整多字节字符）时，SubmitReceipt 必须整体返回
12	// ErrInvalidArgument 和空回执确认，不能靠静默替换（U+FFFD）、截断或跳过
13	// 坏字节继续登记，也不能让当次内存里保留原字节、重开后却变成替换字符。
14	// 合法 UTF-8 原因（含中文、换行、引号、反斜杠、首尾空白与用户明确输入的
15	// 合法 U+FFFD）必须原样保存与比较，当次内部查看与关闭重开后的查看逐字
16	// 相同。接受回执继续忽略传入原因：即使被忽略的原因夹带坏字节，也不能
17	// 拒绝接受或改变相同接受回执的重交结果。
18	
19	// invalidRejectionReasons 是各类无效 UTF-8 拒绝原因：坏序列出现在开头、
20	// 结尾、中间，夹在合法中文之间，孤立续字节，不完整多字节字符，单个非法
21	// 字节，overlong 编码与 UTF-16 代理项编码；另有一例在合法 U+FFFD 之后
22	// 紧跟非法字节——必须因那个坏字节被拒绝。
23	var invalidRejectionReasons = []struct {
24		label  string
25		reason string
26	}{
27		{"开头非法字节", "\xff拒绝：内容不完整"},
28		{"结尾非法字节", "拒绝：内容不完整\xff"},
29		{"中间非法字节", "拒绝\xff：内容不完整"},
30		{"中文之间夹坏字节", "记录缺\xfe失，拒绝接收"},
31		{"孤立续字节", "拒绝接收\x80"},
32		{"结尾不完整多字节字符", "拒绝接收：记录\xe6"},
33		{"中间不完整多字节序列", "ab\xe6\x9d拒绝cd"},
34		{"中文之后截断三字节序列", "拒绝接收：记录\xe7\xa1"},
35		{"最后一个多字节字符没有写完整", "拒收原因\xe4\xb8"},
36		{"单个非法字节", "\x80"},
37		{"overlong 编码", "拒绝\xc0\x80原因"},
38		{"UTF-16 代理项编码", "第一行\n\xed\xa0\x80\n第二行"},
39		{"合法替换字符后紧跟非法字节", "拒绝：补充\ufffd\xff"},
40	}
41	
42	// validRejectionReasons 是必须逐字原样保存的合法 UTF-8 拒绝原因。
43	var validRejectionReasons = []struct {
44		label  string
45		reason string
46	}{
47		{"纯中文", "记录不完整，拒绝接收"},
48		{"中文与全角标点", "诊断：内容与摘要不符（复核确认）"},
49		{"表情字符", "内容异常 🩸，拒绝接收 😷"},
50		{"换行引号反斜杠", "  第一行\n第二行\t\"引号\" 与 C:\\路径  "},
51		{"首尾空白保留", "\t\n  拒绝原因保持原样  \r\n "},
52		{"用户明确输入的合法替换字符", "拒绝：补充\ufffd（用户明确输入的 U+FFFD）"},
53	}
54	
55	// receiptUTF8Fixture 是回执原因 UTF-8 测试的夹具：一名患者、一次就诊、
