294	// TestSubmitReceiptExplicitReplacementCharIsLegal 守住“用户明确输入的合法
295	// U+FFFD 可以保存，它与无效字节不是一回事”：明确含 U+FFFD 的原因登记成功
296	// 并原样往返；只有对应位置换成坏字节的同形原因必须被 ErrInvalidArgument
297	// 拒绝，既不能命中已保存的那份回执，也不能在重开后与其变成同一个原因。
298	func TestSubmitReceiptExplicitReplacementCharIsLegal(t *testing.T) {
299		dir := t.TempDir()
300		clk := &fakeClock{t: time.Date(2026, 6, 6, 9, 0, 0, 0, time.UTC)}
301		open := func() *Store {
302			s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
303			if err != nil {
304				t.Fatalf("open: %v", err)
305			}
306			return s
307		}
308	
309		s := open()
310		f := setupReceiptUTF8(t, s, clk)
311		x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-rcpt-fffd")
312		if err != nil {
313			t.Fatal(err)
314		}
315	
316		// 用户明确输入的合法 U+FFFD 原因可以正常登记。
317		explicit := "拒绝：补充\ufffd"
318		conf, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, explicit)
319		if err != nil {
320			t.Fatalf("register reason with explicit U+FFFD: %v", err)
321		}
322		auditBefore := mustAudit(t, s, f.pid)
323	
324		// 同形位置换成坏字节的原因：参数错误，而不是“原因相同”的确认或
325		// “原因不同”的冲突——坏字节根本不允许进入登记判定。
326		bad := "拒绝：补充\xff"
327		if c, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, bad); !errors.Is(err, ErrInvalidArgument) {
328			t.Fatalf("bad-byte lookalike reason err = %v, confirmation = %+v, want ErrInvalidArgument", err, c)
329		}
330		got := mustGetExchange(t, s, f.pid, x.ID)
331		if got.Receipt == nil || got.Receipt.Reason != explicit {
332			t.Fatalf("saved reason changed after rejected lookalike: %+v", got.Receipt)
333		}
334		if audit, err := s.AuditEvents(doc, f.pid); err != nil || !reflect.DeepEqual(audit, auditBefore) {
335			t.Fatalf("audit changed after rejected lookalike: %v", err)
336		}
337	
338		// 关闭重开：保存的仍是明确的合法 U+FFFD，原样重交返回首次确认。
339		s = reopenStore(t, s, dir, clk)
340		t.Cleanup(func() { _ = s.Close() })
341		got = mustGetExchange(t, s, f.pid, x.ID)
342		if got.Receipt == nil || got.Receipt.Reason != explicit ||
343			!got.Receipt.RegisteredAt.Equal(conf.RegisteredAt) {
344			t.Fatalf("reason changed across reopen: %+v", got.Receipt)
345		}
346		again, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptRejected, explicit)
347		if err != nil {
348			t.Fatalf("resubmit explicit U+FFFD after reopen: %v", err)
349		}
350		if again.ExchangeID != conf.ExchangeID || !again.RegisteredAt.Equal(conf.RegisteredAt) {
351			t.Fatalf("resubmit after reopen changed confirmation: got %+v, want %+v", again, conf)
352		}
353	}
354	
355	// TestSubmitReceiptAcceptedIgnoresInvalidUTF8Reason 覆盖接受回执：传入原因
356	// 一律被忽略并保存为空，即使原因夹带无效字节，也不能因此拒绝接受或改变
357	// 相同接受回执的重交结果（返回首次确认、不新增审计、关闭重开后一致）。
358	func TestSubmitReceiptAcceptedIgnoresInvalidUTF8Reason(t *testing.T) {
359		for _, tc := range []struct {
360			label  string
361			reason string
362		}{
363			{"坏字节开头", "\xff随手附带的接受文字"},
364			{"坏字节结尾", "随手附带的接受文字\xff"},
365			{"不完整多字节字符", "随手附带\xe7\xa1"},
366			{"单个非法字节", "\x80"},
367			{"普通合法文字", "首次登记时随手附带的接受文字"},
368		} {
369			t.Run(tc.label, func(t *testing.T) {
370				dir := t.TempDir()
371				clk := &fakeClock{t: time.Date(2026, 6, 7, 9, 0, 0, 0, time.UTC)}
372				open := func() *Store {
373					s, err := Open(dir, WithClock(func() time.Time { return clk.t }))
374					if err != nil {
375						t.Fatalf("open: %v", err)
376					}
377					return s
378				}
379	
380				s := open()
381				f := setupReceiptUTF8(t, s, clk)
382				x, err := s.CreateExchange(doc, f.pid, rcv.ID, f.auth.ID, []ID{f.rid}, "req-acc-utf8-"+tc.label)
383				if err != nil {
384					t.Fatal(err)
385				}
386	
387				conf, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, tc.reason)
388				if err != nil {
389					t.Fatalf("accept with ignored bad-byte reason: %v", err)
390				}
391				if conf.Status != ExchangeAccepted || conf.Outcome != ReceiptAccepted || conf.RegisteredAt.IsZero() {
392					t.Fatalf("unexpected accept confirmation: %+v", conf)
393				}
394				got := mustGetExchange(t, s, f.pid, x.ID)
395				if got.Status != ExchangeAccepted || got.Receipt == nil ||
396					got.Receipt.Outcome != ReceiptAccepted || got.Receipt.Reason != "" {
397					t.Fatalf("accepted receipt must store empty reason, got %+v", got.Receipt)
398				}
399	
400				// 用另一段同样夹带坏字节（字节都不同）的原因重交接受：被忽略，
401				// 仍返回首次确认，不新增审计。
402				clk.t = clk.t.Add(2 * time.Hour)
403				again, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, "重交时另一段坏字节\xfe文字")
404				if err != nil {
405					t.Fatalf("accept resubmit with another bad-byte reason: %v", err)
406				}
407				if again.ExchangeID != conf.ExchangeID || !again.RegisteredAt.Equal(conf.RegisteredAt) {
408					t.Fatalf("accept resubmit changed confirmation: got %+v, want %+v", again, conf)
409				}
410				if c := receiptAuditCount(t, s, f.pid); c != 1 {
411					t.Fatalf("accept resubmit changed receipt audit count: %d", c)
412				}
413				got = mustGetExchange(t, s, f.pid, x.ID)
414				if got.Receipt.Reason != "" {
415					t.Fatalf("ignored reason leaked into saved receipt: %+v", got.Receipt)
416				}
417	
418				// 关闭重开：接受状态与空原因保持，重交仍返回首次确认。
419				s = reopenStore(t, s, dir, clk)
420				t.Cleanup(func() { _ = s.Close() })
421				got = mustGetExchange(t, s, f.pid, x.ID)
422				if got.Status != ExchangeAccepted || got.Receipt == nil || got.Receipt.Reason != "" ||
423					!got.Receipt.RegisteredAt.Equal(conf.RegisteredAt) {
424					t.Fatalf("accepted receipt changed across reopen: %+v", got.Receipt)
425				}
426				again2, err := s.SubmitReceipt(rcv, x.ID, x.Digest, ReceiptAccepted, "\xff\xff")
427				if err != nil {
428					t.Fatalf("accept resubmit after reopen: %v", err)
429				}
430				if again2.ExchangeID != conf.ExchangeID || !again2.RegisteredAt.Equal(conf.RegisteredAt) {
431					t.Fatalf("accept resubmit after reopen changed confirmation: got %+v, want %+v", again2, conf)
432				}
433				if c := receiptAuditCount(t, s, f.pid); c != 1 {
434					t.Fatalf("resubmit after reopen changed receipt audit count: %d", c)
435				}
436			})
437		}
438	}
